import sys

def find_subgrid(S, T):
    N, M = len(S), len(T)

    if M > N:
        print("No match")
        return

    if not T:
        print("0 0")
        return

    for i in range(N - M + 1):
        for j in range(N - M + 1):
            match = True
            for x in range(M):
                for y in range(M):
                    if S[i + x][j + y] != T[x][y]:
                        match = False
                        break
                if not match:
                    break
            if match:
                print(i + 1, j + 1)
                return

    print("No match")

if __name__ == "__main__":
    input = sys.stdin.read
    data = input().split()
    N = int(data[0])
    M = int(data[1])
    S = [data[i:i+N] for i in range(2, 2+N*N, N)]
    T = [data[i:i+M] for i in range(2+N*N, 2+N*N+M*M, M)]
    find_subgrid(S, T)
